"use server";

import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { db } from "@/lib/db";
import { SESSION_COOKIE } from "@/lib/session";

export async function login(formData: FormData) {
  const userId = formData.get("userId");
  const sessionId = typeof userId === "string" ? await db.createSession(userId) : null;
  if (!sessionId) redirect("/login");

  const cookieStore = await cookies();
  cookieStore.set(SESSION_COOKIE, sessionId, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: 60 * 60 * 8,
  });
  redirect("/dashboard");
}

export async function logout() {
  const cookieStore = await cookies();
  cookieStore.delete(SESSION_COOKIE);
  redirect("/login");
}

import Link from "next/link";
import { db } from "@/lib/db";
import { login } from "./actions";

export default async function LoginPage() {
  const users = await db.listUsers();

  return (
    <main className="flex flex-1 items-center justify-center px-6 py-16">
      <div className="w-full max-w-sm space-y-6 rounded-xl border border-slate-200 bg-white p-8 shadow-sm">
        <div className="space-y-1">
          <h1 className="text-xl font-semibold">LeadDesk</h1>
          <p className="text-sm text-slate-500">Демо-вхід: оберіть користувача, пароль не потрібен.</p>
        </div>

        <form action={login} className="space-y-4">
          <label className="block text-sm font-medium">
            Користувач
            <select
              name="userId"
              className="mt-1 block w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
            >
              {users.map((user) => (
                <option key={user.id} value={user.id}>
                  {user.name} · {user.workspaceSlug}
                </option>
              ))}
            </select>
          </label>
          <button
            type="submit"
            className="w-full rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-700"
          >
            Увійти
          </button>
        </form>

        <Link href="/" className="block text-center text-sm text-slate-500 hover:text-slate-900">
          ← Форма заявки
        </Link>
      </div>
    </main>
  );
}

import { logout } from "@/app/login/actions";
import { getCurrentUser, getWorkspace } from "@/lib/data";

export async function DashboardHeader() {
  const user = await getCurrentUser();
  const workspace = await getWorkspace({ slug: user.workspaceSlug });

  return (
    <header className="flex items-center justify-between border-b border-slate-200 bg-white px-6 py-3">
      <div>
        <p className="text-sm font-medium">{workspace.name}</p>
        <p className="text-xs text-slate-500">{workspace.timezone}</p>
      </div>
      <div className="flex items-center gap-4">
        <div className="text-right">
          <p className="text-sm">{user.name}</p>
          <p className="text-xs text-slate-500">{user.role}</p>
        </div>
        <form action={logout}>
          <button type="submit" className="rounded-md border border-slate-300 px-3 py-1.5 text-xs hover:bg-slate-50">
            Вийти
          </button>
        </form>
      </div>
    </header>
  );
}

