317	      const leads = store.leads.filter((lead) => lead.workspaceId === workspaceId);
318	      const byStatus = Object.fromEntries(LEAD_STATUSES.map((s) => [s, 0])) as Record<LeadStatus, number>;
319	      for (const lead of leads) byStatus[lead.status]++;
