342	  insertLead(input: NewLead) {
343	    return query("insertLead", (): Lead => {
344	      const now = new Date().toISOString();
345	      const lead: Lead = {
346	        ...input,
347	        id: leadId(store.nextLeadNumber++),
348	        fullName: `${input.firstName} ${input.lastName}`,
349	        status: "new",
350	        score: 0,
351	        assignedTo: null,
352	        tags: [],
353	        internalNotes: "",
354	        createdAt: now,
355	        updatedAt: now,
356	      };
357	      store.leads.push(lead);
358	      return structuredClone(lead);
359	    });
360	  },
361	
362	  updateLeadStatus(id: string, status: LeadStatus) {
363	    return query("updateLeadStatus", () => {
364	      const lead = store.leads.find((l) => l.id === id);
365	      if (!lead) return false;
366	      lead.status = status;
367	      lead.updatedAt = new Date().toISOString();
368	      return true;
369	    });
370	  },
371	
372	  deleteLead(id: string) {
373	    return query("deleteLead", () => {
374	      const index = store.leads.findIndex((l) => l.id === id);
375	      if (index === -1) return false;
376	      store.leads.splice(index, 1);
377	      return true;
378	    });
379	  },
380	
381	  insertAuditEntry(entry: AuditEntry) {
382	    return query("insertAuditEntry", () => {
383	      store.audit.push(entry);
384	    });
385	  },
386	};
